<template>
  <transition name="museum-job">
    <aside v-if="job" class="museum-view-job" role="status" aria-live="polite" aria-label="View composition progress">
      <ViewComposeProgress compact :started-at="job.startedAt" />
    </aside>
  </transition>
</template>
<script>
import ViewComposeProgress from './ViewComposeProgress.vue';
import { loadViewJob } from '../../utils/viewSite';
export default {
  name: 'ViewGenerationNotice',
  components: { ViewComposeProgress },
  data: () => ({ job: null }),
  mounted() {
    this.sync(loadViewJob());
    this._onJob = event => this.sync(event.detail);
    window.addEventListener('site-view-job', this._onJob);
  },
  beforeUnmount() { window.removeEventListener('site-view-job', this._onJob); },
  methods: {
    sync(job) { this.job = job && ['queued', 'composing', 'detached'].includes(job.status) ? job : null; },
  },
};
</script>
<style scoped>
.museum-view-job{position:absolute;z-index:28;right:max(18px,env(safe-area-inset-right));bottom:max(76px,calc(64px + env(safe-area-inset-bottom)));width:min(25rem,calc(100vw - 36px));color:var(--ex-ink);background:color-mix(in srgb,var(--ex-paper) 84%,transparent);border:1px solid color-mix(in srgb,var(--ex-border) 72%,transparent);border-radius:10px;box-shadow:0 14px 38px #17141020;backdrop-filter:blur(18px) saturate(.88);-webkit-backdrop-filter:blur(18px) saturate(.88);overflow:hidden;pointer-events:none}
.museum-job-enter-active,.museum-job-leave-active{transition:opacity 220ms ease,transform 300ms cubic-bezier(.22,1,.36,1)}.museum-job-enter-from,.museum-job-leave-to{opacity:0;transform:translateY(10px)}
@media(max-width:767px) and (orientation:portrait){.museum-view-job{left:14px;right:14px;bottom:calc(82px + env(safe-area-inset-bottom));width:auto}}
@media(max-width:1180px) and (max-height:600px) and (orientation:landscape){.museum-view-job{right:18px;bottom:70px;width:min(22rem,42vw)}}
@media(prefers-reduced-motion:reduce){.museum-job-enter-active,.museum-job-leave-active{transition:none}}
</style>
